`timescale 1ns / 1ps
// weapon_overlay: every pixel of the idle frame and of the firing frame
// (recoil + muzzle flash) against golden frames generated by
// scripts/gen_weapon_overlay.py straight from the sprite drawing; hidden when
// show=0; a lowered gun (reload) is the idle sprite moved down by drop rows and
// is gone at drop>=24.
// weapon_ctrl FSM + reload sub-machine: 6-round magazine, one shot_fired per
// accepted shot, fire ignored during recoil, reload and outside play, automatic
// reload on empty, manual reload (ignored when full, remembered during recoil),
// reload phases LOWER -> SWAP -> RAISE with their lengths and gun movement,
// magazine refilled at the end of SWAP, reset when play ends.
module tb_weapon;
    reg [6:0] px=0; reg [5:0] py=0;
    reg show=1, recoil=0, flash=0;
    reg [4:0] drop=0;
    reg [15:0] pixel_in=0;
    wire [15:0] pixel_out;
    weapon_overlay dut(.px(px),.py(py),.show(show),.recoil(recoil),.flash(flash),.drop(drop),
        .pixel_in(pixel_in),.pixel_out(pixel_out));
    reg [15:0] golden [0:12287];
    reg clk=0; always #5 clk=~clk;
    reg rst=1, playing=0, fire=0, reload=0;
    wire wflash, wrecoil, shot, wreloading;
    wire [2:0] ammo; wire [4:0] wdrop; wire [1:0] wstate, phase;
    localparam RS=6;                                    // RELOAD_SHIFT in this test
    weapon_ctrl #(.FLASH_SHIFT(4),.RECOIL_SHIFT(6),.RELOAD_SHIFT(RS)) ctrl(.clk(clk),.rst(rst),
        .playing(playing),.fire(fire),.reload(reload),.flash(wflash),.recoil(wrecoil),
        .shot_fired(shot),.ammo(ammo),.reloading(wreloading),.drop(wdrop),
        .state(wstate),.reload_phase(phase));
    integer f,x,y,d,failures=0,shots=0,flash_len=0,recoil_len=0,fd,src,k;
    integer reloads=0, phase_len=0, max_drop=0;
    reg [1:0] last_phase=0; reg [4:0] last_drop=0; reg [2:0] last_ammo=6;
    reg [15:0] expected;
    integer di[0:5];
    task fail;
        input [511:0] msg;
        begin failures=failures+1; $display("FAIL weapon: %0s",msg); end
    endtask
    // ---- FSM monitor: phase order and length, drop direction, refill point ----
    always @(posedge clk) if(playing && !rst) begin
        if(shot) shots=shots+1;
        if(wflash) flash_len=flash_len+1;
        if(wrecoil) recoil_len=recoil_len+1;
        if(wreloading && wrecoil) fail("reloading and recoiling at once");
        if(!wreloading && wdrop!=0) fail("gun lowered outside a reload");
        if(phase!=last_phase) begin
            if(!((last_phase==0 && phase==1) || (last_phase==1 && phase==2) ||
                 (last_phase==2 && phase==3) || (last_phase==3 && phase==0)))
                fail("reload phases out of order");
            if(last_phase!=0 && (phase_len<(1<<RS) || phase_len>(1<<RS)+1))
                fail("reload phase length");
            if(last_phase==1) reloads=reloads+1;
            phase_len=1;
        end else phase_len=phase_len+1;
        if(phase==1 && last_phase==1 && wdrop<last_drop) fail("gun moved up while lowering");
        if(phase==2 && wdrop!=31) fail("gun visible during the magazine swap");
        if(phase==3 && last_phase==3 && wdrop>last_drop) fail("gun moved down while raising");
        if(wdrop>max_drop) max_drop=wdrop;
        if(ammo>last_ammo && !(last_phase==2 && phase==3))
            fail("magazine refilled outside the end of the swap");
        last_phase=phase; last_drop=wdrop; last_ammo=ammo;
    end
    task pulse_fire;
        begin @(negedge clk); fire=1; @(negedge clk); fire=0; end
    endtask
    task pulse_reload;
        begin @(negedge clk); reload=1; @(negedge clk); reload=0; end
    endtask
    task wait_ready;                                    // back to W_READY
        begin
            k=0; while(wstate!=0 && k<2000) begin @(negedge clk); k=k+1; end
            if(wstate!=0) fail("weapon did not return to ready");
        end
    endtask
    initial begin
        // Golden frames: found next to the simulation, or in the source tree when
        // run by scripts/run_sim.py (build/sim_weapon) or a Vivado project.
        fd=$fopen("weapon_golden.hex","r");
        if(fd!=0) begin $fclose(fd); $readmemh("weapon_golden.hex", golden); end
        else begin
            fd=$fopen("../../sim/weapon_golden.hex","r");
            if(fd!=0) begin $fclose(fd); $readmemh("../../sim/weapon_golden.hex", golden); end
            else begin
                fd=$fopen("../../../../sim/weapon_golden.hex","r");
                if(fd!=0) begin $fclose(fd); $readmemh("../../../../sim/weapon_golden.hex", golden); end
                else begin $display("FAIL weapon: weapon_golden.hex not found (add it to the simulation sources)"); $finish; end
            end
        end
        for(f=0;f<2;f=f+1) begin
            recoil=f; flash=f;
            for(y=0;y<64;y=y+1) for(x=0;x<96;x=x+1) begin
                px=x; py=y; pixel_in=(x*7+y*13); #1;
                if(pixel_out!==golden[f*6144+y*96+x]) begin
                    failures=failures+1;
                    if(failures<6) $display("FAIL weapon: frame %0d (%0d,%0d) got %h expected %h",f,x,y,pixel_out,golden[f*6144+y*96+x]);
                end
            end
        end
        // Lowered gun: idle sprite moved down by drop rows (sprite pixels are where
        // the golden idle frame differs from its own background pattern).
        recoil=0; flash=0;
        di[0]=1; di[1]=5; di[2]=12; di[3]=23; di[4]=24; di[5]=31;
        for(d=0;d<6;d=d+1) begin
            drop=di[d];
            for(y=0;y<64;y=y+1) for(x=0;x<96;x=x+1) begin
                px=x; py=y; pixel_in=(x*7+y*13); #1;
                src=y-di[d];
                expected=pixel_in;
                if(src>=0 && golden[src*96+x]!==((x*7+src*13) & 16'hFFFF)) expected=golden[src*96+x];
                if(pixel_out!==expected) begin
                    failures=failures+1;
                    if(failures<6) $display("FAIL weapon: drop %0d (%0d,%0d) got %h expected %h",di[d],x,y,pixel_out,expected);
                end
                if(di[d]>=24 && pixel_out!==pixel_in) begin
                    failures=failures+1; if(failures<6) $display("FAIL weapon: gun visible at drop %0d",di[d]);
                end
            end
        end
        drop=0;
        show=0; recoil=1; flash=1;
        for(y=0;y<64;y=y+1) for(x=0;x<96;x=x+1) begin
            px=x; py=y; pixel_in=(x*7+y*13); #1;
            if(pixel_out!==pixel_in) begin failures=failures+1; if(failures<6) $display("FAIL weapon: drawn while hidden"); end
        end
        // Preview of the idle and firing frames over the real sky/floor.
        fd=$fopen("weapon_preview.ppm","w"); $fwrite(fd,"P3\n192 64\n255\n");
        show=1;
        for(y=0;y<64;y=y+1) for(f=0;f<192;f=f+1) begin
            px=f%96; py=y; recoil=f/96; flash=f/96; pixel_in=(y<32) ? 16'h1084 : 16'h3166; #1;
            $fwrite(fd,"%0d %0d %0d\n",pixel_out[15:11]*255/31,pixel_out[10:5]*255/63,pixel_out[4:0]*255/31);
        end
        $fclose(fd);
        // ---- weapon_ctrl ----
        repeat(3) @(negedge clk); rst=0;
        pulse_fire; pulse_reload; repeat(100) @(negedge clk);
        if(shot || wflash || wreloading || ammo!=6) fail("fired or reloaded while not playing");
        playing=1; @(negedge clk);
        if(ammo!=6) fail("game does not start with a full magazine");
        pulse_reload; repeat(5) @(negedge clk);
        if(wreloading) fail("reload accepted with a full magazine");
        pulse_fire;
        repeat(20) @(negedge clk);
        pulse_fire;                                   // during recoil: ignored
        repeat(100) @(negedge clk);
        if(shots!=1 || ammo!=5) fail("shot during recoil was not ignored / ammo not 5");
        if(flash_len<16 || flash_len>18) fail("flash length (must be one continuous 2^FLASH_SHIFT burst)");
        if(recoil_len<64 || recoil_len>66) fail("recoil length");
        // Empty the magazine: 5 more shots, then the reload starts by itself.
        repeat(4) begin pulse_fire; @(negedge clk); wait_ready; end
        pulse_fire; @(negedge clk);                  // sixth round
        if(shots!=6 || ammo!=0) fail("six rounds per magazine");
        k=0; while(!wreloading && k<200) begin @(negedge clk); k=k+1; end
        if(!wreloading) fail("no automatic reload on an empty magazine");
        pulse_fire; repeat(30) @(negedge clk); pulse_fire;   // during reload: ignored
        wait_ready;
        if(shots!=6) fail("fired during the reload");
        if(ammo!=6) fail("reload did not refill the magazine");
        if(reloads!=1) fail("expected one reload");
        if(max_drop!=31) fail("gun did not go fully out of view");
        // Manual reload in READY with a partial magazine.
        pulse_fire; @(negedge clk); wait_ready; pulse_fire; @(negedge clk); wait_ready;
        if(ammo!=4) fail("ammo after two shots");
        pulse_reload; repeat(3) @(negedge clk);
        if(!wreloading) fail("manual reload not accepted");
        wait_ready;
        if(ammo!=6 || reloads!=2) fail("manual reload did not refill");
        // Reload pressed during recoil is remembered.
        pulse_fire; repeat(10) @(negedge clk); pulse_reload;
        k=0; while(!wreloading && k<200) begin @(negedge clk); k=k+1; end
        if(!wreloading) fail("reload pressed during recoil was lost");
        wait_ready;
        if(ammo!=6 || reloads!=3) fail("remembered reload did not refill");
        // Leaving play mid-reload resets the weapon.
        pulse_fire; @(negedge clk); wait_ready; pulse_reload; repeat(50) @(negedge clk);
        if(!wreloading) fail("reload for the reset check did not start");
        playing=0; @(negedge clk); @(negedge clk);
        if(wreloading || ammo!=6 || wstate!=0) fail("leaving play did not reset the weapon");
        if(failures==0) $display("PASS weapon: idle, firing and lowered frames match the sprite drawing pixel for pixel, hidden with the map; FSM: 6-round magazine, one shot_fired per shot, fire ignored during recoil/reload/outside play, auto reload on empty, manual reload (ignored when full, remembered in recoil), LOWER->SWAP->RAISE phases with lengths and gun movement, refill at end of swap, reset on leaving play (%0d reloads)",reloads);
        else $display("FAIL weapon total=%0d",failures);
        $finish;
    end
endmodule
